int process_auth_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket *ticket = NULL;
    void *ticket_end = NULL;
    struct ceph_auth_handler *handler = NULL;

    if (!ac || !secret || !p || !end || *p >= end) {
        goto out;
    }

    /* Decode ticket type and version */
    if (end - *p < sizeof(__le32) * 2) {
        goto out;
    }

    __le32 *type = (__le32 *)(*p);
    __le32 *version = (__le32 *)(*p + sizeof(__le32));
    *p += sizeof(__le32) * 2;

    handler = ceph_get_auth_handler(le32_to_cpu(*type));
    if (!handler) {
        ret = -ENOPROTOOPT;
        goto out;
    }

    if (handler->version != le32_to_cpu(*version)) {
        ret = -EPROTONOSUPPORT;
        goto out;
    }

    /* Allocate memory for the ticket structure */
    ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
    if (!ticket) {
        ret = -ENOMEM;
        goto out;
    }

    ticket_end = *p;
    ret = ceph_decode_auth_ticket(ticket, &ticket_end, end, secret, handler);
    if (ret < 0) {
        goto out;
    }

    /* Update the session key and ticket blob if valid */
    if (ceph_ticket_is_valid(ticket)) {
        if (ac->session_key.value) {
            kfree(ac->session_key.value);
        }

        ac->session_key.value = kmemdup(ticket->session_key.value, ticket->session_key.length, GFP_NOFS);
        if (!ac->session_key.value) {
            ret = -ENOMEM;
            goto out;
        }

        ac->session_key.length = ticket->session_key.length;

        if (ac->ticket_blob.value) {
            kfree(ac->ticket_blob.value);
        }

        ac->ticket_blob.value = kmemdup(ticket->blob.value, ticket->blob.length, GFP_NOFS);
        if (!ac->ticket_blob.value) {
            ret = -ENOMEM;
            goto out;
        }

        ac->ticket_blob.length = ticket->blob.length;
        ret = 0;
    }

out:
    if (handler) {
        ceph_put_auth_handler(handler);
    }

    if (ticket) {
        kfree(ticket);
    }

    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
  int ret = -EINVAL;
  struct ceph_auth_ticket_handler *handler = NULL;
  struct ceph_auth_ticket *ticket = NULL;
  void *ticket_end = NULL;
  struct ceph_crypto_key *session_key = NULL;

  // Decode the ticket type and version
  if ((end - *p) < sizeof(uint32_t) * 2) {
    goto out;
  }

  uint32_t ticket_type = ceph_decode_32(p);
  uint32_t version = ceph_decode_32(p);

  handler = ceph_auth_get_ticket_handler(ac, ticket_type);
  if (!handler) {
    goto out;
  }

  // Validate the ticket structure
  if ((end - *p) < sizeof(uint32_t)) {
    goto out;
  }

  uint32_t ticket_len = ceph_decode_32(p);
  ticket_end = *p + ticket_len;
  if (ticket_end > end) {
    goto out;
  }

  ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
  if (!ticket) {
    ret = -ENOMEM;
    goto out;
  }

  ret = handler->decode_ticket(ticket, p, ticket_end);
  if (ret < 0) {
    goto out;
  }

  // Decrypt the ticket using the secret key
  ret = ceph_decrypt_ticket(ticket, secret);
  if (ret < 0) {
    goto out;
  }

  // Update the session key and ticket blob
  session_key = ceph_copy_crypto_key(&ticket->session_key);
  if (!session_key) {
    ret = -ENOMEM;
    goto out;
  }

  ac->session_key = session_key;
  ceph_copy_ticket_blob(ac, &ticket->blob);

  ret = 0;

out:
  if (ret < 0) {
    ceph_free_crypto_key(session_key);
    kfree(ticket);
  }
  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    void *ticket_start = *p;
    uint32_t ticket_type, version;
    struct ceph_auth_client_ticket_handler *handler = NULL;
    struct ceph_auth_ticket *ticket = NULL;

    if (!ac || !secret || !p || !*p || !end || *p >= end) {
        goto out;
    }

    if (ceph_decode_dout(*p, end, &ticket_type) < 0) {
        goto out;
    }
    (*p) += sizeof(uint32_t);

    if (ceph_decode_dout(*p, end, &version) < 0) {
        goto out;
    }
    (*p) += sizeof(uint32_t);

    handler = ceph_auth_client_get_ticket_handler(ac, ticket_type);
    if (!handler) {
        ret = -ENOTSUP;
        goto out;
    }

    ticket = handler->decode_ticket(*p, end - *p);
    if (!ticket) {
        goto out;
    }

    ret = handler->decrypt_ticket(ticket, secret);
    if (ret < 0) {
        goto out;
    }

    if (ticket->valid_after > ac->now ||
        ticket->valid_until <= ac->now) {
        ret = -ETIMEDOUT;
        goto out;
    }

    ac->session_key = ticket->session_key;
    ac->ticket_blob = ticket->blob;
    ac->ticket_blob_len = ticket->blob_len;

    ret = 0;
out:
    if (ticket && ticket->blob) {
        free(ticket->blob);
    }
    if (ticket) {
        free(ticket);
    }
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    void *ticket_start = *p;
    uint32_t ticket_type, version;
    struct ceph_auth_ticket_handler *handler = NULL;
    struct ceph_auth_ticket *ticket = NULL;

    if ((end - *p) < sizeof(ticket_type) + sizeof(version)) {
        goto out;
    }

    ceph_decode_copy(p, &ticket_type, sizeof(ticket_type));
    ceph_decode_copy(p, &version, sizeof(version));

    handler = ceph_auth_get_ticket_handler(ticket_type);
    if (!handler) {
        ret = -ENOPROTOOPT;
        goto out;
    }

    ticket = handler->decode_ticket(p, end);
    if (IS_ERR_OR_NULL(ticket)) {
        ret = PTR_ERR_OR_ZERO(ticket);
        goto out;
    }

    ret = handler->decrypt_ticket(ticket, secret);
    if (ret < 0) {
        goto out;
    }

    if (ticket->timestamp > ac->last_session_seq) {
        ac->last_session_seq = ticket->timestamp;
        ceph_crypto_key_free(ac->session_key);
        ac->session_key = ceph_crypto_key_dup(&ticket->session_key);
        if (!ac->session_key) {
            ret = -ENOMEM;
            goto out;
        }
    }

    if (ticket->blob) {
        ceph_blob_set(&ac->ticket_blob, ticket->blob, ticket->blob_len);
    }

    ret = 0;
out:
    if (ret < 0) {
        ceph_auth_ticket_free(ticket);
    }
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    void *ticket_start = *p;
    struct ceph_auth_ticket_header *header = NULL;
    struct ceph_auth_ticket_handler *handler = NULL;
    struct ceph_crypto_key *session_key = NULL;

    // Decode ticket header
    if (*p + sizeof(*header) > end) {
        goto out;
    }
    header = (struct ceph_auth_ticket_header *)*p;
    *p += sizeof(*header);

    // Find ticket handler
    handler = ceph_auth_ticket_get_handler(ac, header->type);
    if (!handler) {
        goto out;
    }

    // Decrypt and verify ticket data
    ret = handler->decrypt_ticket(ac, secret, &header->ticket_data, *p, end);
    if (ret < 0) {
        goto out;
    }

    // Allocate session key
    session_key = ceph_crypto_key_alloc();
    if (!session_key) {
        ret = -ENOMEM;
        goto out;
    }

    // Update session key and ticket blob
    ret = handler->update_session_key(ac, session_key, &header->ticket_data);
    if (ret < 0) {
        goto out;
    }

    ac->ticket_blob = ceph_buffer_create(*p, end - *p);
    if (!ac->ticket_blob) {
        ret = -ENOMEM;
        goto out;
    }

    ret = 0;

out:
    if (ret < 0) {
        ceph_crypto_key_free(session_key);
        ceph_buffer_free(ac->ticket_blob);
    }
    *p = ticket_start;
    return ret;
}
